// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import java.io.IOException;

import org.eclipse.kura.KuraException;
import org.junit.Test;

public class EnforcementMonitorRestartTest extends AbstractEnforcementTest {

    private static final long RESTART_DELAY_SECONDS = 10;

    @Test
    public void failedEventStreamSchedulesARestart() {
        givenStartedEnforcement();

        whenEventStreamFails();

        thenScheduledDelaysAre(RESTART_DELAY_SECONDS);
    }

    @Test
    public void failedFirstConnectionSchedulesARestart() {
        givenNextConnectionFails();

        whenEnforcementStarts();

        thenScheduledDelaysAre(RESTART_DELAY_SECONDS);
    }

    @Test
    public void startEventsAreEnforcedAfterTheMonitorRestarts() throws KuraException {
        givenContainerWithImageDigest(CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcement();
        givenEventStreamFailed();
        givenScheduledDelayElapsed();

        whenStartEventArrivesFor(CONTAINER_ID);

        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void containerStartedWhileTheMonitorWasDownIsDeletedOnRestart() throws KuraException {
        givenStartedEnforcement();
        givenEventStreamFailed();
        givenContainerStartedWhileTheMonitorWasDown();

        whenScheduledDelayElapses();

        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void failedReconnectionDoesNotSweep() {
        givenStartedEnforcement();
        givenEventStreamFailed();
        givenNextConnectionFails();

        whenScheduledDelayElapses();

        thenContainersWereListed(1);
    }

    @Test
    public void failedRestartSchedulesAnotherRestart() {
        givenStartedEnforcement();
        givenEventStreamFailed();
        givenNextConnectionFails();

        whenScheduledDelayElapses();

        thenScheduledDelaysAre(RESTART_DELAY_SECONDS, RESTART_DELAY_SECONDS);
    }

    @Test
    public void startEventsAreEnforcedAfterARetriedRestart() throws KuraException {
        givenContainerWithImageDigest(CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcement();
        givenEventStreamFailed();
        givenFirstRestartFailed();
        givenScheduledDelayElapsed();

        whenStartEventArrivesFor(CONTAINER_ID);

        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void unexpectedRestartErrorIsRetried() {
        givenStartedEnforcement();
        givenEventStreamFailed();
        givenNextSubscriptionThrowsUnexpectedly();

        whenScheduledDelayElapses();

        thenScheduledDelaysAre(RESTART_DELAY_SECONDS, RESTART_DELAY_SECONDS);
    }

    @Test
    public void completedEventStreamIsRestarted() {
        givenStartedEnforcement();
        givenEventStreamCompleted();

        whenScheduledDelayElapses();

        thenEventsWereSubscribed(2);
    }

    @Test
    public void eventStreamEndingAfterCloseIsNotRestarted() {
        givenStartedEnforcement();
        givenClosedEnforcement();

        whenEventStreamFails();

        thenNothingWasScheduled();
    }

    private void givenEventStreamCompleted() {
        this.events.completeStream();
    }

    private void givenContainerStartedWhileTheMonitorWasDown() {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        this.events.publishStart(CONTAINER_ID);
    }

    private void givenNextSubscriptionThrowsUnexpectedly() {
        this.events.failNextSubscriptionWith(new IllegalStateException("unexpected client error"));
    }

    private void givenFirstRestartFailed() {
        givenNextConnectionFails();
        givenScheduledDelayElapsed();
    }

    private void givenScheduledDelayElapsed() {
        this.scheduler.runScheduledTasks();
    }

    private void whenEventStreamFails() {
        this.events.failStream(new IOException("connection to docker lost"));
    }
}
